html:
{% set copies = [
    ("Original",      "e-invoice"),
    ("Duplicate",     "e-invoice"),
    ("Triplicate",    "e-invoice"),
    ("Quadruplicate", "e-invoice")
] %}

{# ── Pre-compute common values (once) ── #}
{% set dn_name = doc.items[0].delivery_note if (doc.items and doc.items[0].delivery_note) else "" %}
{% set dn_date = frappe.db.get_value("Delivery Note", dn_name, "posting_date") if dn_name else None %}
{% set eway_created = frappe.db.get_value("e-Waybill Log", {"reference_name": doc.name}, "created_on") %}
{% set po_date = frappe.db.get_value("Sales Order", doc.items[0].sales_order, "po_date") if (doc.items and doc.items[0].sales_order) else "" %}
{% set qr_src = "" %}
{% if doc.irn %}
    {% set _log = frappe.get_doc("e-Invoice Log", doc.irn) %}
    {% if _log and _log.signed_qr_code %}
        {% set qr_src = "data:image/png;base64," + get_qr_code(_log.signed_qr_code) %}
    {% endif %}
{% endif %}
{% set addr = frappe.get_doc("Address", doc.customer_address) if doc.customer_address else None %}
{% set ship = frappe.get_doc("Address", doc.shipping_address_name) if doc.shipping_address_name else None %}
{% set cus = frappe.get_doc("Customer", doc.customer_name) if doc.customer_name else None %}

{# ── Pagination (computed once) ── #}
{% set ns = namespace(cur=[], h=0, pages=[]) %}
{% for item in doc.items %}
    {% set nl = ((item.description or "")|string).count('\n') %}
    {% set wr = (((item.description or "")|length) / 50)|int %}
    {% set lines = 1 + nl + wr %}
    {% if (ns.h + lines) > 28 %}
        {% set _ = ns.pages.append(ns.cur) %}
        {% set ns.cur = [item] %}
        {% set ns.h = lines %}
    {% else %}
        {% set _ = ns.cur.append(item) %}
        {% set ns.h = ns.h + lines %}
    {% endif %}
{% endfor %}
{% if ns.cur %}{% set _ = ns.pages.append(ns.cur) %}{% endif %}

{# ── Render 4 copies × N pages ── #}
{% set outer = namespace(last_copy=false) %}
{% for copy_label, copy_sub in copies %}
{% set outer.last_copy = loop.last %}
{% for batch in ns.pages %}
{% set is_last_page_of_copy = loop.last %}
{% set needs_break = (not is_last_page_of_copy) or (not outer.last_copy) %}

<div class="spring-container {% if needs_break %}page-break{% endif %}">
<div class="content-wrapper">

<!-- ═══ HEADER ═══ -->
<table style="width:100%;border-collapse:collapse;border:1px solid black;height:4.8cm;table-layout:fixed;">
  <tr>
    <td width="45%" style="vertical-align:top;padding:5px;border:none;">
      <div style="margin-bottom:5px;margin-top:0.8cm;padding-right:42px;">
        <img src="/files/ujwal.png" style="height:1.8cm;width:5.5cm;object-fit:contain;">
      </div>
      <div style="font-size:9px;line-height:1.4;">
        <b>Works :</b> Plot No. W-53 &amp; W-53/1, Phase II, MIDC Dombivli (E),<br>
        Dist, Thane - 421204, MS - INDIA.<br>
        <b>Tel:</b> 91-9833390161 / 91-8691055543<br>
        <b>Email:</b> sales.ujwal@ivisiongroup.co.in<br>
        <b style="font-size:11px;">GSTIN No : 27ADZPB3303R1Z0</b>
      </div>
    </td>
    <td width="32%" style="vertical-align:middle;border:none;padding:5px;">
      <div style="display: flex; flex-direction: column; justify-content: space-between; height: 100%;">
            <div style="text-align : left">
                <div style="font-size:16px; font-weight:bold; border-bottom: 1px solid black; display: inline-block; padding-bottom: 2px;">TAX-INVOICE</div>
                <div style="font-size:8px; margin-top: 3px;">Under Rule 7 of GST Rules 2017</div>
            </div>

            <div style="margin-top: 10px;">
                <div style="font-size: 10px; font-weight:bold; text-align: left; font-weight: semi-bold">
                    <br><br><br><br><br><br><br>
                    IRN NO:<br/>
                    <span style="font-family: monospace; font-weight: semi-bold; word-break: break-all; line-height: 1.1; display: block; width: 100%;">
                        {{ doc.irn or "" }}
                    </span>
                </div>
            </div>
        </div>
    </td>
    <td width="23%" style="vertical-align:top;padding:5px;border:none;text-align:right;">
          <div style="font-size: 9px; text-align: right;">Original</div>
                <div style="font-size: 11px; font-weight: bold; text-align: right;">e-invoice</div>
                <div style="margin-top: 4px; margin-left: 6px; text-align: left;">
                    {% set qr_image_src = "" %}
                    {% if doc.irn %}
                        {% set log_doc = frappe.get_doc("e-Invoice Log", doc.irn) %}
                        {% if log_doc and log_doc.signed_qr_code %}
                            {% set qr_image_src = "data:image/png;base64," + get_qr_code(log_doc.signed_qr_code) %}
                        {% endif %}
                    {% endif %}
                    {% if qr_image_src %}
                        <img src="{{ qr_image_src }}" style="width: 2.6cm; height: 2.6cm; object-fit: contain; display: inline-block;">
                    {% else %}
                        <div style="width: 2.6cm; height: 2.6cm; border: 1px dashed #aaa; font-size: 7px; color: #aaa; display: inline-flex; align-items: center; justify-content: center; text-align: center;">
                            QR NOT<br>GENERATED
                        </div>
                    {% endif %}
                </div>

                <div style="font-size: 8px; margin-top: 4px; margin-left: 6px; text-align: left;">
                    <b>IRN DT: {{ frappe.utils.formatdate(doc.posting_date, "dd-MMM-yyyy") | upper }}</b>
                </div>
    </td>
  </tr>
</table>

<!-- ═══ INFO ROW ═══ -->
<table class="master-table" style="border-top:none;height:0.9cm;">
  <tr>
    <td width="45.5%" class="text-bold">Name of Goods Division: {{ doc.custom_name_of_goods_division or "SWITCHGEAR" }}</td>
    <td width="18.5%" class="text-bold">INVOICE NO</td>
    <td width="17%">{{ doc.name }}</td>
    <td width="6.25%" class="text-bold">Date</td>
    <td width="12.5%">{{ doc.posting_date }}</td>
  </tr>
  <tr>
    <td width="45.5%" style="vertical-align:top;">
      <div style="font-size:9.5px; "><b>Name & Address of Consignee:</b> 
                {% if doc.customer_address %}
                {% set custom_addr = frappe.get_doc("Address" , doc.customer_address) %}
                </div>
                    <div style="font-size:11px; margin:3px 0;">
                    {% if doc.customer_name %}
                        {% set cus = frappe.get_doc("Customer" , doc.customer_name) %}
                        {{cus.custom_customer_names or ""}} - {{ doc.customer_name }}
                    {% endif %}    
                    </div>
                    <div style="font-size:9.5px; line-height: 1.3;">
                        {{ custom_addr.address_line1 }} {{ custom_addr.address_line2 }} {{ custom_addr.state }} {{ custom_addr.pincode or ""}}
                    </div>
                {% endif %}
                <div style="margin-top:10px; font-size: 14.5px;">GST No. : <b>
                    {% if doc.customer_address %}
                    {% set custom_addr = frappe.get_doc("Address" , doc.customer_address) %}
                        {{ custom_addr.gstin or "" }}</b>
                     {% endif %}
                </div>
    </td>
    <td width="19.5%" class="text-bold" style="padding:3px !important;">
      <div style="border-bottom:0.5px solid black;">PO NO</div>
      <div style="border-bottom:0.5px solid black;">Our Challan No.</div>
      <div style="border-bottom:0.5px solid black;">G.R.N No.</div>
      <div style="border-bottom:0.5px solid black;">EWay Bill No.</div>
      <div>Vendor Code No</div>
    </td>
    <td width="17%" style="padding:3px !important;vertical-align:top;">
      <div style="border-bottom:1px solid black;">{{ doc.po_no or "&nbsp;" }}</div>
      <div style="border-bottom:1px solid black;">{{ dn_name or "&nbsp;" }}</div>
      <div style="border-bottom:1px solid black;">{{ doc.grn_no or "&nbsp;" }}</div>
      <div style="border-bottom:1px solid black;">{{ doc.ewaybill or "&nbsp;" }}</div>
      <div>{{ doc.vendor_code or "&nbsp;" }}</div>
    </td>
    <td width="5.25%" style="padding:3px !important;vertical-align:middle;text-align:center;">
      <div style="border-bottom:1px solid black;">Date</div>
      <div style="border-bottom:1px solid black;">Date</div>
      <div style="border-bottom:1px solid black;">Date</div>
      <div style="border-bottom:1px solid black;">Date</div>
    </td>
    <td width="12.5%" style="padding:3px !important;">
      <div style="border-bottom:1px solid black;">{{ frappe.utils.formatdate(po_date, "dd-MM-yyyy") if po_date else "&nbsp;" }}</div>
      <div style="border-bottom:1px solid black;">{{ frappe.utils.formatdate(dn_date, "dd-MM-yyyy") if dn_date else "&nbsp;" }}</div>
      <div style="border-bottom:1px solid black;">&nbsp;</div>
      <div style="border-bottom:1px solid black;">{{ frappe.utils.formatdate(eway_created, "dd-MM-yyyy") if eway_created else "&nbsp;" }}</div>
    </td>
  </tr>
</table>

<!-- ═══ ITEMS TABLE ═══ -->
<table style="width:100%;border-collapse:collapse;border:1px solid black;border-top:none;table-layout:fixed;">
  <thead>
    <tr class="text-center text-bold">
      <td rowspan="2" style="width:5%;padding:3px;border:1px solid black;">Pos n No.</td>
      <td rowspan="2" style="width:30%;padding:3px;border:1px solid black;">PARTICULAR / Description of Goods</td>
      <td rowspan="2" style="width:10.5%;padding:3px;border:1px solid black;">HSN</td>
      <td colspan="2" style="width:19.5%;padding:3px;border:1px solid black;">PACKING</td>
      <td rowspan="2" style="width:10%;padding:3px;border:1px solid black;">QTY</td>
      <td rowspan="2" style="width:7.5%;padding:3px;border:1px solid black;">Rate (₹)</td>
      <td rowspan="2" style="width:17.5%;padding:3px;border:1px solid black;">Amt (₹)</td>
    </tr>
    <tr class="text-center text-bold">
      <td style="width:45px;border:1px solid black;">No of Pkgs</td>
      <td style="width:45px;border:1px solid black;">Avg cont.</td>
    </tr>
  </thead>
  <tbody>
    {% for row in batch %}
    <tr>
      <td class="text-center" style="border:1px solid black;">{{ row.custom_po_no or "" }}</td>
      <td style="vertical-align:top;border:1px solid black;">
        <b>{{ row.item_name }}</b><br>
        <span style="font-size:8.5px;color:#333;">{{ row.description or "" }}</span>
      </td>
      <td class="text-center" style="border:1px solid black;">{{ row.gst_hsn_code or "" }}</td>
      <td class="text-center" style="border:1px solid black;">{{ row.custom_no_of_packages or "" }}</td>
      <td class="text-center" style="border:1px solid black;">{{ row.custom_avg_content or "" }}</td>
      <td class="text-center" style="border:1px solid black;">
        {{ row.qty|int }}<br>
        <div style="font-size:8px;">{{ row.uom }}</div>
      </td>
      <td class="text-right" style="border:1px solid black;">{{ row.rate or "" }}</td>
      <td class="text-right" style="border:1px solid black;">{{ row.amount|int }}</td>
    </tr>
    {% endfor %}
    {% for i in range(5 - (batch|length)) %}
    <tr>
      <td style="height:25px;border-left:1px solid black;border-right:1px solid black;"></td>
      <td style="border:none;border-right:1px solid black;"></td>
      <td style="border:none;border-right:1px solid black;"></td>
      <td style="border:none;border-right:1px solid black;"></td>
      <td style="border:none;border-right:1px solid black;"></td>
      <td style="border:none;border-right:1px solid black;"></td>
      <td style="border:none;border-right:1px solid black;"></td>
      <td style="border:none;border-right:1px solid black;"></td>
    </tr>
    {% endfor %}
  </tbody>
</table>

</div>{# end content-wrapper #}

<!-- ═══ FOOTER ═══ -->
<div class="footer-wrapper">
{% if is_last_page_of_copy %}

  <table class="master-table" style="border-top:none;">
    <tr>
      <td width="65%" style="padding:0!important;vertical-align:top;border-right:1px solid black;">
        <div style="padding:5px;border-bottom:1px solid black;font-size:10px;">{{ doc.base_in_words|upper }}</div>
        {% set t = namespace(cgst=0,sgst=0,igst=0) %}
        {% for tax in doc.taxes %}
          {% if "CGST" in tax.account_head %}{% set t.cgst = t.cgst + tax.tax_amount %}{% endif %}
          {% if "SGST" in tax.account_head %}{% set t.sgst = t.sgst + tax.tax_amount %}{% endif %}
          {% if "IGST" in tax.account_head %}{% set t.igst = t.igst + tax.tax_amount %}{% endif %}
        {% endfor %}
        <div style="padding:5px;border-bottom:1px solid black;font-size:7px;font-weight:900;" class="text-uppercase">CGST : {{ frappe.utils.in_words(t.cgst|int) }}</div>
        <div style="padding:5px;border-bottom:1px solid black;font-size:7px;font-weight:900;" class="text-uppercase">SGST : {{ frappe.utils.in_words(t.sgst|int) }}</div>
        <div style="padding:5px;border-bottom:1px solid black;font-size:7px;">IGST : {{ frappe.utils.in_words(t.igst|int) if t.igst > 0 else "NIL" }}</div>
        <div style="padding:5px;border-bottom:1px solid black;font-weight:bold;">Amount In Words : {{ doc.in_words }}</div>
        <div style="padding:6px;">
          <b>Ship To Party :</b>
          {% if doc.shipping_address_name %}
           {% set custom_addr = frappe.get_doc("Address" , doc.shipping_address_name) %}
             {{ custom_addr.address_line1 }} {{ custom_addr.address_line2 }} {{ custom_addr.state }}
            <div style="margin-top: 5px;"><b>GSTIN : {{ custom_addr.gstin or "" }}</b></div>
          {% endif %}
        </div>
      </td>
      <td width="35%" style="padding:0;vertical-align:top;">
        <table style="width:100%;border-collapse:collapse;">
          <tr>
            <td width="60%" class="text-bold" style="padding:4px;border-bottom:1px solid black;">Assasable Value</td>
            <td class="text-right" style="padding:4px;border-bottom:1px solid black;border-left:1px solid black;">{{ doc.base_net_total|int }}</td>
