          {% for tax in doc.taxes %}{% if tax.tax_amount != 0 %}
          <tr>
            <td class="text-bold" style="padding:4px;border-bottom:1px solid black;">{{ tax.description }}</td>
            <td class="text-right" style="padding:4px;border-bottom:1px solid black;border-left:1px solid black;">{{ tax.tax_amount|int }}</td>
          </tr>
          {% endif %}{% endfor %}
          <tr style="height:35px;">
            <td colspan="2" style="padding:4px;border-bottom:1px solid black;"><b>Mode of Transport Vehicle No :-</b> {{ doc.vehicle_no or "" }}</td>
          </tr>
          <tr style="font-weight:bold;">
            <td style="padding:6px;">Total Amount</td>
            <td class="text-right" style="padding:6px;border-left:1px solid black;">{{ doc.grand_total|int }}</td>
          </tr>
        </table>
      </td>
    </tr>
  </table>

  <table class="master-table">
    <tr class="text-center text-bold" style="background:#eee;">
      <td rowspan="2" width="15%">HSN/SAC</td>
      <td rowspan="2" width="20%">Taxable Value</td>
      <td colspan="2">Central Tax</td>
      <td colspan="2">State Tax</td>
      <td rowspan="2" width="15%">Total Tax</td>
    </tr>
    <tr class="text-center text-bold" style="background:#eee;">
      <td>Rate</td><td>Amount</td><td>Rate</td><td>Amount</td>
    </tr>
    {% for group in doc.items|groupby("gst_hsn_code") %}
    <tr class="text-right">
      <td class="text-center">{{ group.grouper }}</td>
      <td>{{ doc.base_net_total|int if loop.first else "0" }}</td>
      <td class="text-center">9.00</td>
      <td>{{ (doc.total_taxes_and_charges/2)|int if loop.first else "0" }}</td>
      <td class="text-center">9.00</td>
      <td>{{ (doc.total_taxes_and_charges/2)|int if loop.first else "0" }}</td>
      <td>{{ doc.total_taxes_and_charges|int if loop.first else "0" }}</td>
    </tr>
    {% endfor %}
  </table>

  <table class="master-table" style="border-top:none;margin-top:5px;">
    <tr>
      <td width="60%" style="font-size:8.2px;vertical-align:top;padding:8px;line-height:1.4;">
        <b>TERMS &amp; CONDITION</b><br>
        1. Goods once sold will not be taken back.<br>
        2. Interest @ 24% p.a will be charged, if this invoice is not paid by due date.<br>
        3. We reserve our rights to recover the amount in part or full of bill at any time.<br>
        4. No complaints in respect of material supplied vide this invoice will be entertained unless the same is lodged in writing within 15 days of dispatch.<br>
        5. SUBJECT TO KALYAN JURISDICTION.
      </td>
      <td width="40%" style="text-align:center;padding:10px;">
        <div style="font-size:14px;font-weight:bold;margin-bottom:40px;">Ujwal Industries</div>
        <div style="font-size:8px;border-top:1px solid #000;display:inline-block;">(Authorised Signatory)</div>
      </td>
    </tr>
  </table>

{% else %}
  <div style="text-align:center;padding:10px;font-weight:bold;border-top:1px solid black;">Continued to Next Page...</div>
{% endif %}
</div>

</div>{# end spring-container #}

{% endfor %}{# end pages #}
{% endfor %}{# end copies #}

